void LibraryScanController::onScanSummary(const LibraryScanResultSummary& result) {
    m_scanning = false;
    m_currentPath.clear();
    if (m_cancelRequested || result.cancelled) {
        m_analyzeAfterScan = false;
        m_cancelRequested = false;
        m_progress = 0;
        m_status = tr("Scan annulé");
    } else if (!result.success) {
        m_analyzeAfterScan = false;
        m_progress = 0;
        m_status = tr("Scan interrompu : certains dossiers n’ont pas pu être lus");
    } else if (result.noDirectoriesConfigured) {
        m_analyzeAfterScan = false;
        m_progress = 0;
        m_status = tr("Ajoutez un dossier musical dans Préférences → Bibliothèque");
    } else if (m_analyzeAfterScan) {
        m_analyzeAfterScan = false;
        m_preparing = true;
        m_status = tr("Recherche des BPM et tonalités manquants…");
        emit changed();
        emit analysisRequested();
        return;
    } else {
        m_progress = m_analyzing ? -1 : 100;
        m_status = tr("Scan terminé : %1 nouveaux titres, %2 absents")
                           .arg(result.numNewTracks).arg(result.numMissingTracks);
    }
    emit changed();
}

void LibraryScanController::onAnalysisActive(bool active) {
    const bool wasAnalyzing = m_analyzing;
    m_analyzing = active;
    if (m_scanning) {
        emit changed();
        return;
    }
    m_preparing = false;
    if (active) {
        m_progress = -1;
        m_status = tr("Analyse BPM et tonalité · %1 cœurs")
                           .arg(qMax(1, QThread::idealThreadCount()));
    } else if (wasAnalyzing) {
        m_progress = m_cancelRequested ? 0 : 100;
        m_status = m_cancelRequested ? tr("Analyse arrêtée") : tr("Analyse terminée");
        m_cancelRequested = false;
    }
    emit changed();
}

void LibraryScanController::onAnalysisProgress(AnalyzerProgress, int current, int total) {
    if (!m_analyzing || m_scanning || m_cancelRequested || total <= 0) {
        return;
    }
    m_progress = qBound(0, static_cast<int>(100.0 * current / total), 99);
    m_status = tr("Analyse BPM et tonalité : %1 / %2 · %3 % · %4 cœurs")
                       .arg(current).arg(total).arg(m_progress)
                       .arg(qMax(1, QThread::idealThreadCount()));
    emit changed();
}

void LibraryScanController::onNoAnalysisNeeded() {
    m_preparing = false;
    if (m_analyzing) {
        onAnalysisActive(true);
        return;
    }
    m_progress = 100;
    m_status = tr("Scan terminé · BPM et tonalités déjà disponibles");
    emit changed();
}

void LibraryScanController::onError(const QString& message) {
    m_preparing = false;
    m_analyzeAfterScan = false;
    m_progress = 0;
    m_status = message;
    emit changed();
}
